                cls_fields[field_name] = 'DatabaseBlob'
            elif field_type == 'date':
                cls_fields[field_name] = 'datetime.date'
            elif field_type == 'time':
                cls_fields[field_name] = 'datetime.time'
            elif field_type == 'datetime':
                cls_fields[field_name] = 'datetime.datetime'
            else:
                cls_fields[field_name] = 'str'

