def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *,
         color: bool = False,
         target_concurrency: int = 1,
         _max_length: int = _get_platform_max_length(),
         **kwargs: Any) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """

    if color:
        import pty

    if color and not supports_pty():
        raise Exception("GTK supports color by default when being called through X, it cannot be activated if run without X")

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be positive")

    if _max_length < 1:
        raise ValueError("max_length must be positive")

    return (len(varargs) + 1, b' '.join(cmd + varargs).encode('utf-8'))

