def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on Windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    flags = []
    newcmd = []

    for item in cmd:
        if item.startswith("#!") and item.find(' ') == -1:
            flags.append(item)
            newcmd.append('#!/windows/system32/bash.exe ' + item.replace('#!', ''))
        else:
            newcmd.append(item)

    return tuple(newcmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if cmd[0].startswith("!\\"):  
        cmd[0] = cmd[0][1:]  
        for i in range(2, len(cmd)):
            if cmd[i].startswith("!\\"):  
                cmd[i] += cmd[i+1]  
                cmd[i+1] = "" 
    return tuple(cmd)

