def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
        up to `maxsize` results based on a Least Recently Used (LRU)
        algorithm with a per-item time-to-live (TTL) value.
        """
    func_cache = {}
    def wrapper(*args, **kw):
        key = (args, kw)
        if key not in func_cache:
            func_cache[key] = func(*args, **kw)
            timestamp = timer() + ttl
            func_cache[key][-1] = timestamp
        else:
            entry = func_cache[key]
            if timer() - entry[-1] > ttl:
                func_cache.pop(key)
                func_cache[key] = func(*args, **kw)
                func_cache[key][-1] = timestamp
        return func_cache[key][0]

    if typed:
        wrapper = functools.lru_cache(maxsize=maxsize, typed=True)
    else:
        wrapper = functools.lru_cache(maxsize=maxsize)

