    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    cache = {}
    hits = {}
    misses = {}
    calls = 0

    def memoized_function(*args, ** kwargs):
        nonlocal calls
        calls += 1
        key = (args, kwargs)
        hits[key] = calls - misses[key] if key in hits else calls
        misses[key] = calls
        if key in cache:
            if typed:
                return cache[key]
            else:
                value = cache[key]
                if value not in cache:
                    raise KeyError(f"KeyError: {key}")
                return value
        else:
            if maxsize > 0:
                if len(cache) >= maxsize:
                    least_used = min(hits.values())
                    least_used_keys = [k for k, v in hits.items() if v == least_used]
                    del cache[least_used_keys[0]]
                    del hits[least_used_keys[0]]
                    misses[least_used_keys[0]] = 0
            cache[key] = memoized_function(*args, ** kwargs)
            if typed:
                return cache[key]
            else:
                return cache[key]

    return memoized_function

