def extostr(e: Exception, max_level: int = 30, max_path_level: int = 5) -> str:
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    def _get_exception_type(e):
        if hasattr(e, '__cause__'):
            return _get_exception_type(e.__cause__)
        elif hasattr(e, '__context__'):
            return _get_exception_type(e.__context__)
        else:
            return type(e).__name__

    def _get_exception_details(e):
        if hasattr(e, '__cause__'):
            details = _get_exception_details(e.__cause__)
        elif hasattr(e, '__context__'):
            details = _get_exception_details(e.__context__)
        else:
            details = str(e)

        parts = [.details]

        try:
            last_caller = inspect.getframeinfo(sys._getframe())
            caller_file = last_caller.filename
            caller_line = last_caller.lineno
        except ValueError:
            caller_file = '<unknown>'
            caller_line = '?'

        parts.append(f'File {caller_file}, line {caller_line}')
        parts.append(f'Cause {', '.join([_get_exception_type(ex) for ex in e.__cause__ if ex is not None])}')

        if hasattr(e, '__context__') and len(e.__context__) > 0:
            contexts = [f'ContextedException {ex.__class__.__name__}: {ex.message}' for ex in e.__context__]
            parts.append(print(contexts))

        return '\n'.join(parts)

    return _get_exception_details(e)

