def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent

    Args:
        classes (list): A list of base classes.

    Returns:
        list: An ordered list of minimal base classes.
    """
    from collections import deque

    def bfs(node):
        visited = set()
        queue = deque([(node, 0)])

        while queue:
            node, depth = queue.popleft()
            if node not in visited:
                visited.add(node)
                queue.extend([(child, depth + 1) for child in node.children if child not in visited])

        return reversed(visited)

    minimal = set(classes)
    for c in classes:
        for cc in classes:
            if c is not cc:
                if c.is_parent_of(cc) or cc.is_parent_of(c):
                    minimal -= {c, cc}

    minimal = bfs(minimal)
    return list(minimal)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent
    """
    seen = set()
    result = []

    for cls in classes:
        if cls not in seen:
            result.append(cls)
            seen.add(cls)

    return result

def minimalBases(classes):
    classes.sort(key=lambda x: len(x))
    while len(classes) > 1:
        if len(classes[-1]) > len(classes[-2]):
            classes.pop(-1)
        elif len(classes[-1]) == len(classes[-2]):
            classes.pop()
    return classes

