        'Source': set(),
        'State': set(),
        'Time': set(),
        'tiebreak': set(),
        'key values': set()
    })
    for attrib in ['E','t','error_E_low','j','k','l']:
        if hasattr(self,attrib) and isinstance(getattr(self,attrib), str):
