def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1 or level == 0:
        if d1 == d2:
            return {}
        elif level == 0:
            return {}
        else:
            return {k: v for k, v in d1.items() if k not in d2}

    if isinstance(d1, dict) and isinstance(d2, dict):
        if len(d1) > len(d2):
            return {k: difference(d1[k], d2, level - 1) for k in d1 if k not in d2}
        else:
            return {k: difference(d1[k], d2, level - 1) for k in d2 if k in d1}
    elif isinstance(d1, list) and isinstance(d2, list):
        if len(d1) > len(d2):
            return [difference(d1[i], d2, level - 1) for i in range(len(d1))]
        else:
            return [difference(d1[i], d2, level - 1) for i in range(len(d2))]
    else:
        return {d1: d1}

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level < 0:
        return d1

    diff = {}
    for key, value in d1.items():
        if key not in d2 or value != d2[key]:
            diff[key] = value

    for key, value in diff.items():
        if isinstance(value, dict):
            diff[key] = difference(d1.get(key, {}), d2.get(key, {}), level - 1)
        elif isinstance(value, list):
            diff[key] = [item for item in value if item not in d2.get(key, [])]

    return diff

