    for key in d2:
        if key in d1:
            if level != -1 and key in d1[key] and type(d1[key]) == type(d2[key]) and isinstance(d1[key], dict) and isinstance(d2[key], dict) and level > 0:
                result[key] = difference(d1[key], d2[key], level - 1)
            elif level != -1 and key in d1[key] and type(d1[key]) == type(d2[key]) and isinstance(d1[key], list) and isinstance(d2[key], list) and level > 0:
