def generate_default_observer_schema_dict(manifest_dict, first_level=False):
        """Together with :func:`generate_default_observer_schema_list`, this function is
        called recursively to generate part of a default ``observer_schema`` from part of a
        Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

        Args:
            manifest_dict (dict): Partial Kubernetes resources
            first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

        Returns:
            dict: Generated partial observer_schema

        This function creates a new dictionary from ``manifest_dict`` and replaces all
        non-list and non-dict values by ``None``.

        In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
        resource), the values of the identifying fields are copied from the manifest file.

        """
        obs_schema = {}

        for k, v in manifest_dict.items():
            if isinstance(v, dict):
                obs_schema[k] = generate_default_observer_schema_dict(v, first_level=False)
            elif isinstance(v, list):
                obs_schema[k] = [None] * len(v)  # Replace list values with None
            else:
                obs_schema[k] = None

        if first_level:
            # Copy identifying fields from the manifest file if it's the first level
            if 'kind' in manifest_dict:
                obs_schema['kind'] = manifest_dict['kind']
            if 'metadata' in manifest_dict:
                if 'name' in manifest_dict['metadata']:
                    obs_schema['metadata']['name'] = manifest_dict['metadata']['name']
                if 'namespace' in manifest_dict['metadata']:
                    obs_schema['metadata']['namespace'] = manifest_dict['metadata']['namespace']

        return obs_schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
        """
        Together with :func:``generate_default_observer_schema_list``, this function is
        called recursively to generate part of a default ``observer_schema`` from part of a
        Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

        Args:
            manifest_dict (dict): Partial Kubernetes resources
            first_level (bool, optional): If True, indicates that the dictionary represents
                the whole observer schema of a Kubernetes resource

        Returns:
            dict: Generated partial observer_schema

        This function creates a new dictionary from ``manifest_dict`` and replaces all
        non-list and non-dict values by ``None``.

        In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
        resource), the values of the identifying fields are copied from the manifest file.
        """
        schema_dict = {}

        for key, value in manifest_dict.items():
            if isinstance(value, dict):
                schema_dict[key] = generate_default_observer_schema_dict(value, first_level=False)
            elif isinstance(value, list):
                schema_dict[key] = [generate_default_observer_schema_dict(item, first_level=False) for item in value]
            else:
                schema_dict[key] = None

        # Copy identifying fields from manifest file to first_level dictionary
        if first_level:
            for field in manifest_dict.get('spec', {}).get('identifying_fields', []):
                if field in schema_dict:
                    schema_dict[field] = manifest_dict.get('spec', {}).get('identifying_fields', {}).get(field)

        return schema_dict

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    observation_type = manifest_dict.get('apiVersion')
    if observation_type != "ExampleAPI/v1":
        return

    result = {
        "resourceType": manifest_dict.get('kind'),
        "allOf": [
            {
                "type": "object",
                "properties": {
                    "apiVersion": {
                        "description": "API version of the Kubernetes resource",
                        "type": "string"
                    },
                    "kind": {
                        "description": "Kind of the Kubernetes resource",
                        "type": "string"
                    },
                    "metadata": {
                        "description": "Metadata of the Kubernetes resource",
                        "type": "object",
                        "properties": {
                            "name": {
                                "description": "Name of the Kubernetes resource",
                                "type": "string"
                            }
                        }
                    },
                    "spec": {
                        "description": "Specification of the Kubernetes resource",
                        "type": "object"
                    }
                }
            }
        ]
    }

    metadata = {}
    if first_level:
        metadata['name'] = manifest_dict['metadata']['name']
        metadata['apiVersion'] = manifest_dict['apiVersion']
        metadata['kind'] = manifest_dict['kind']

    keys = manifest_dict.get('spec', {}).keys()
    for key in keys:
        # Recursively call for substructures (e.g., arrays, objects)
        if key in manifest_dict['spec'] and isinstance(manifest_dict['spec'][key], (list, dict)):
            result['allOf'][0]['properties'][key] = {
                "description": "Substructure of the Kubernetes resource",
                "type": "object",
                "properties": {},
                "additionalProperties": True
            }
            recursive_substructure = generate_default_observer_schema_dict(manifest_dict['spec'][key], True)
            result['allOf'][0]['properties'][key]['properties'] = recursive_substructure['properties']
            if 'properties' in recursive_substructure:
                recursive_substructure['properties'].pop('additionalProperties')
        else:
            result['allOf'][0]['properties'][key] = {
                "type": "string"
            }

    return result

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
