                        last_applied_manifest[f"{item['kind']}s/{item['metadata']['name']}_creation_timestamp"] = item['metadata']['creationTimestamp']
                except KeyError:
                    pass
            elif item['kind'] == 'ConfigMap':
                try:
                    if 'metadata' in item and 'creationTimestamp' in item['metadata']:
                        last_applied_manifest[f"{item['kind']}s/{item['metadata']['name']}_creation_timestamp"] = item['metadata']['creationTimestamp']
                except KeyError:
                    pass
            elif item['kind'] == 'Service':
                try:
                    if 'metadata' in item and 'creationTimestamp' in item['metadata']:
                        last_applied_manifest[f"{item['kind']}s/{item['metadata']['name']}_creation_timestamp"] = item['metadata']['creationTimestamp']
                except KeyError:
                    pass
            elif item['kind'] == 'Secret':
                try:
                    if 'metadata' in item and 'creationTimestamp' in item['metadata']:
                        last_applied_manifest[f"{item['kind']}s/{item['metadata']['name']}_creation_timestamp"] = item['metadata']['creationTimestamp']
