    for field, schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"Observed field '{field}' not present in Kubernetes response")
        if isinstance(schema, dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest.get(field, {}), schema, response[field])
        else:
            last_applied_manifest[field] = response[field]

