def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]):
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
            contains the set of in-style parameters. It maps each parameter
            (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
            is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
            If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
            *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	A :class:`list` containing each set of converted out-style
    	parameters (:class:`dict` or :class:`list`).
    """
    if not hasattr(self, 'SQLParams') or not self.SQLParams.in_style:
        return sql, many_params

    formatted_sql = sql
    new_params = []

    for params in many_params:
        try:
            new_params.append(self._format_params(params))
        except Exception as e:
            if isinstance(e, SQLVendorError):
                pass
            else:
                raise e

    return formatted_sql, new_params

#private helper method for formatting parameters
def _format_params(self, params):
    if isinstance(params, Mapping):
        result = {}
        for key, value in params.items():
            try:
                formatted_value = self._format_single_param(value)
                result[key] = formatted_value
            except Exception as e:
                if isinstance(e, SQLVendorError):
                    pass
                else:
                    raise e
    elif isinstance(params, Sequence):
        result = []
        for value in params:
            try:
                formatted_value = self._format_single_param(value)
                result.append(formatted_value)
            except Exception as e:
                if isinstance(e, SQLVendorError):
                    pass
                else:
                    raise e
    return result

#private helper method for formatting a single parameter
def _format_single_param(self, value):
    if not hasattr(self, 'SQLParams') or not self.SQLParams.out_style:
        return value

    if self.SQLParams.out_style == SQLStyle.NAMED:
        params = {self.SQLParams.OUT_PARAM_PREFIX + self._get_param_name(): value}
    elif self.SQLParams.out_style == SQLStyle.ORDINAL:
        params = [value]

    return params

