        """Check all digests in manifest that are needed are present and used."""
        for file in manifest_files:
            digest = file.digest
            if digest not in digests_used:
                raise FileNotFoundError(f"Digest {digest} for file {file.filename} not present or used in manifest")
            if digests_used[digest] != file.digest:
                raise ValueError(f"Digest mismatch for file {file.filename}: expected {digest} but found {digests_used[digest]}")
