            digests_used (List[str]): List of digests to check

        Returns:
            None

        Raises:
            MissingDigestError: If a digest is not found in the manifest
            UsedDigestError: If a digest is used more than once
        """

        # Check if all digests in manifest are present
        for digest in digests_used:
            if digest not in manifest_files:
                raise MissingDigestError("Digest {} not found in manifest.".format(digest))

