def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    number = None
    supplement = None
    parts = issue.split()

    for part in parts:
        if part.isdigit():
            if supplement:
                number = part
                supplement = None
                break
            else:
                number = part
        elif supplement:
            supplement += ' ' + part
        else:
            supplement = part

    if supplement:
        parts = supplement.split()
        for part in parts:
            if part == 'spe':
                supplement = 'spe 1'
                break

    return number, supplement

def _extract_number_and_supplement_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    substrings = issue.findall(r'\d+')
    number = None
    supplement = None
    for substring in substrings:
        if '-sp?' in substring:
            number = substring.split('-sp?')[0]
        elif 'spe' in substring:
            number = substring.split('spe')[0]
        elif 's' in substring:
            number = substring.split('s')[0]
        elif ' suppl' in substring:
            try:
                supplement = substring.split(' suppl')[0]
            except:
                supplement = substring
    return int(number), supplement

