def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    classes = set()
    constructed = []
    current = self
    last_first =>''

    while current:
        if debug: print(f'{indent*4}>{current}')

        if current.__class__.__name__ in classes:
            current = current.next
            continue

        classes.add(current.__class__.__name__)
        parent_index = None
        next_element = current.next

        class_name = current.__class__.__name__
