            if debug:
                element_info += f' {element_annotations}'
                element_info += f' {element_id}'
                element_info += f' {element_occurrences}'

        if parent_index:
            if last_first == '>' or last_first == '\\':
                parent_index = '\r\n'
            elif last_first == '}':
                parent_index = '\n'
            elif last_first == ',' or last_first == ';':
