        self.handlers = {}

    @staticmethod
    def bind(hook_type: HookType, handler: Callable):
        if hook_type in HandlerRegistry.handlers:
            HandlerRegistry.handlers[hook_type].append(handler)
        else:
            HandlerRegistry.handlers[hook_type] = [handler]

    @staticmethod
    def unbind(hook_type: HookType, handler: Callable):
        if hook_type in HandlerRegistry.handlers:
            HandRegistry.handlers[hook_type].remove(handler)
            if not HandlerRegistry.handlers[hook_type]:
                del HandlerRegistry.handlers[hook_type]

    @staticmethod
    def trigger(hook_type: HookType, *args, **kwargs):
        if hook_type in HandlerRegistry.handlers:
            for handler in HandlerRegistry.handlers[hook_type]:
                handler(*args, **kwargs)

