def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s).

    Arguments:
        commands (list): A list of commands and their arguments
        args (dict): A dictionary mapping command names to their arguments
        cwd (str): The working directory, defaults to the current working directory.
        verbose (bool): Print verbose output, defaults to False.
        hide_stderr (bool): Do not print stderr by default, defaults to False.
        env (dict): A dictionary of environment variables, defaults to the current environment.

    Returns:
        tuple: A tuple containing the stdout and stderr of the command(s). Errors are raised if encountered.
    """
    import subprocess

    if cwd is None:
        cwd = os.getcwd()

    if not commands:
        return "", ""

    args_list = []

    for cmd, cmd_args in zip(commands, args.values()):
        if cmd_args is not None:
            if args_list:
                args_list.append(" --arg {0}={1}".format(cmd, cmd_args))
            else:
                args_list.append("--arg {0}={1}".format(cmd, cmd_args))

    proc = subprocess.Popen([cmd] + args_list, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)

    stdout, stderr = proc.communicate()

    if proc.returncode != 0:
        if verbose:
            print(stderr.decode())
        if hide_stderr:
            stderr = ""
        elif verbose:
            print(stdout.decode())
        if hide_stderr:
            stdout = ""
        else:
            print("Command failed: ", end="")
        raise subprocess.CalledProcessError(proc.returncode, " ".join([cmd] + args_list))

    if verbose:
        print(stdout.decode())
    if hide_stderr:
        stdout = ""
    elif verbose:
        print(stderr.decode())
    if hide_stderr:
        stderr = ""

    return stdout, stderr

