import inspect
import sys

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""

    if not callable(method):
        raise TypeError("The method to be decorated must be callable.")

    # Create a decorator that checks if the method is a handler of the VCS
    def vcs_handler_decorator(*args, **kwargs):
        # Get the class that the method belongs to
        cls = inspect.getclasstree(inspect.getouterframes(inspect.currentframe())[2][0])[0][2]

        # Check if the method is a handler of the VCS
        if hasattr(cls, 'vcs_handler') and getattr(cls, 'vcs_handler') == vcs:
            try:
                method(*args, **kwargs)
            except Exception as e:
                print(f"Error in {method.__name__}: {e}")
                sys.exit(1)
            else:
                cls.vcs_handler_on_success()
        else:
            # Raise an error if the method is not a handler of the VCS
            raise ValueError(f"{method.__name__} is not a handler of the VCS.")
    return vcs_handler_decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for obj in self.child_objects():
        if validate_objects:
            error_code = obj.validate()
            if error_code == 0:
                good_objects += 1
            else:
                num_objects += 1
                if show_warnings:
                    print(f"Failed to validate object: {obj.__class__.__name__} with error code {error_code}")
        else:
            num_objects += 1
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
