    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    #list all objects in the storage root
    for obj in self:

        #check object's validity
        if check_objects:
            try:
                if obj.validate():
                    good_objects += 1
                else:
                    num_objects += 1
                    if show_warnings:
                        print("Warning: Object {obj} is invalid.")
            except Exception as e:
                num_objects += 1
                if show_warnings:
                    print(f"Error: Object {obj} is invalid. Error: {e}")

        #check object's digests
        if check_digests:
            try:
