def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        parts = path.split('0=*')
        if len(parts) == 3:
            if parts[1].startswith('Object ID'):
                return 'object'
            elif parts[1].startswith('Inventory ID'):
                return 'file'
        else:
            return 'root'
    except Exception as e:
        return 'other', str(e)

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        # Open the file securely
        with open(path, 'r') as file:
            first_line = file.readline()

            # Check if the first line looks like an OCFL root
            if first_line.startswith('0='):
                return 'root'
            # Check if the first line looks like an OCFL object
            elif first_line.startswith('ocfl-'):
                return 'object'
            # Check if the first line looks like a file
            elif first_line.startswith('storage/'):
                return 'file'
            else:
                return 'other'
    except FileNotFoundError:
        return 'other'  # Path does not exist
    except IOError as e:
        return "Could not read file:" + str(e)

