    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.

    Multiple calls to this function are equivalent: it will only parse new arguments when new subparsers
    have been added to the parser before doing so.
    """
    all_parsers = set()
    global_args = {}
    # Add all subparsers from parsers so far
    for subparser in parsers:
        if subparser.name:
            all_parsers.add(subparser)
    # Parse each subparser and add the results to the global args.
    for idx, arg in enumerate(unparsed_arguments):
        if arg in all_parsers:
            global_args[arg.name] = arg.parse_args(unparsed_arguments[idx*2+1:])
        else:
            global_args[idx] = arg
    # If no subparser, use the global args.
    if idx < len(unparsed_arguments) and not any(parsers) and any(global_args.values()):
        # The global args are positional arguments
        return global_args[0]
    return global_args

