from typing import *
from abc import ABC, abstractmethod

class AbstractElement(ABC):
    @abstractmethod
    def addable(self, class_, parent, **kwargs):
        pass

    @abstractmethod
    def count(self, class_, set_=None, exclude=None, types=None):
        pass

    def replace(self, *args, **kwargs):
        raise NotImplementedError("Replace method is not implemented in AbstractElement.")

    def setdocument(self, doc):
        raise NotImplementedError("setdocument method is not implemented in AbstractElement.")

