class AbstractStructureElement(AbstractElement):
    def __init__(self, id, text=None, type=None):
        self.id = id
        self.text = text
        self.type = type
        self.doc = None
        self.parent = None
        self.children = deque()

    def count(self, class_, set_=None, exclude=None, types=None):
        count = 0
        for child in self.children:
            if isinstance(child, class_):
                count += 1
        return count

    def replace(self, *args, **kwargs):
        for child in self.children:
            if isinstance(child, args[0]):
                child.__dict__.update(kwargs)

    def addable(self, class_, parent, set_=None, raiseexceptions=True):
        if not parent.__class__.accepts(class_, raiseexceptions, parent):
            return False

        if class_.OCCURRENCES > 0:
            #check if the parent doesn't have too many already
            count = parent.count(class_, None, True, [True, AbstractStructureElement])
            if count >= class_.OCCURRENCES:
                if raiseexceptions:
                    if parent.id:
                        extra = ' (id=' + parent.id + ')'
                    else:
                        extra = ''
                    raise DuplicateAnnotationError("Unable to add another object of type " + class__.__name__ + " to " + parent.__class__.__name__ + " " + extra + ". There are already " + str(count) + " instances of this class, which is the maximum.")
                else:
                    return False

        if class_.OCCURRENCES_PER_SET > 0 and set and class_.REQUIRED_ATTRIBS and 'CLASS' in class_.REQUIRED_ATTRIBS:
            count = parent.count(class_, set, True, [True, AbstractStructureElement])
