class PaginatedElement(AbstractStructureElement):
    def __init__(self, max_results, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.max_results = max_results
        self.page = 1
        self.results = []

    def fetch_page(self):
        response = self.get_response()
        self.results = response[:self.max_results]
        if len(response) > self.max_results:
            self.next_page()

    def next_page(self):
        self.page += 1
        self.fetch_page()

    def counts(self, class_, set_=None, exclude=None, types=None):
        if self.page != 1:
            return 0
        page = self.results
        return sum(1 for obj in page if isinstance(obj, class_) if (set_ is None or obj.set == set_) and (exclude is None or obj not in exclude) and (types is None or obj.__class__ in types))

    def get_response(self):
        # Simulate fetching response for demonstration
        return [PaginatedElement(max_results) for _ in range(self.page)]

    def __iter__(self):
        if self.results:
            for result in self.results:
                yield result
            self.fetch_page()
        return self

    def add(self, child):
        if not self.__class__.accepts(child.__class__, False, self):
            raise TypeError("Cannot add object of type " + child.__class__.__name__ + " to this element.")
        child.parent = self
        # Add the child to the page if its count meets the criteria
        if self.counts(child.__class__, None, [self]) > 1:
            self.page += 1
            self.fetch_page()
        self.children.append(child)

    def __contains__(self, child):
        return child in self.children

