def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """

    if not 0 <= number < len(alphabet):
        raise ValueError("Number is out of range for the given alphabet")

    if padding is not None:
        if padding < 0:
            raise ValueError("Padding cannot be negative")
        number = number.ljust(padding, alphabet[0])

    result = []
    while number:
        result.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    return ''.join(reversed(result))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if isinstance(number, str):
        raise ValueError("Number must be an integer")
    if not isinstance(padding, int):
        raise ValueError("Padding must be an integer")

    result = ""
    while number > 0:
        remainder = number % len(alphabet)
        result = alphabet[remainder] + result
        number //= len(alphabet)

    if padding is not None:
        result = result.zfill(padding)

    return result

def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.

    Args:
        number (int): The number to be converted
        alphabet (List[str]): The alphabet to use for the digits
        padding (Optional[int]): The number of leading zeros to add. Defaults to None.

    Returns:
        str: The resulting string representation of the number
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    result = []
    if number == 0:
        result.append('0')
        if padding is not None:
            result.extend(['0'] * padding)
    else:
        while number > 0:
            digit = number % len(alphabet)
            result.append(alphabet[digit])
            number //= len(alphabet)

    if padding is not None and len(result) < padding:
        result.extend(['0'] * (padding - len(result)))

    return ''.join(result[::-1])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not 0 <= number < len(alphabet):
        raise ValueError("Number out of range")
    if padding:
        return '0' * (padding - len(str(number))) + str(number)
    else:
        return str(number)

