import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    pos = platforms['posix']
    win = platforms['windows']
    if platform == 'this':
        platform = pos if os.name == 'posix' else win
    if platform == 0:
        pattern = r'("[^"]*"|"([^"]+)")|([^" ]+)'
    else:
        pattern = r'([^\s"]+)|"([^"]*)"'

    # iterative splitting
    parts = []
    begin = 0
    for match in re.finditer(pattern, s):
        if begin != match.start():
            parts.append(s[begin:match.start()])
        begin = match.end()
        if match.group(1):
            if match.group(1)[0] == '"':
                parts.append(match.group(1)[1:-1])
            else:
                parts.append(match.group(1))
        elif match.group(2):
            parts.append(match.group(2))
        else:
            parts.append(match.group(3))
    if begin < len(s):
        parts.append(s[begin:])
    return parts

