    elif platform == 0:
        shlex_split = re.compile(r'\".*?\"|[^ \t\n\r\'"]+')
        items = shlex_split.findall(s)
        return [item.replace('"', '').strip() for item in items]
    else:
        raise ValueError("Invalid platform value")

