def make_find_paths(find_paths):
    #if path is absolute or regex, do nothing
    if re.match(r'^[a-z][a-z0-9+/=_-]+(/[a-z0-9+/=_-]+)*$', find_paths[0]):
        return find_paths

    #translate path fragments to glob patterns
    glob_patterns = []
    for path in find_paths:
        if path.startswith('glob:'):
            path = path[5:]
        if path.startswith('^'):
            #remove '^'
            path = path[1:]
        if '//' in path:
            #remove double slashes
            path = path.replace('///', '/')
        if path.endswith('/*'):
            #remove trailing /* if it's present
            path = path[:-2:]
        glob_patterns.append(glob.glob(path))

    return glob_patterns

