            return str(path)[:-1] + '/*'
        return path

    transform_pat = re.compile(r'^(.*)\.(.*)$')

    found_paths = []
    for i, path in enumerate(find_paths):
        if path and path.startswith('.'):
            found_paths.append(path)
            continue

        m = transform_pat.match(path)
        if m:
            path_name = m.group(1).strip('.')
            if not m.group(2): continue

            if path_name.startswith('*'):
                # startswith pat
                glob = re.compile(f'^{path_name}.{m.group(2)}')
            else:
                # matches pat
                glob = re.compile(f'{path_name}.{m.group(2)}*')

            found_paths.append(glob)

        found_paths.append(expand_path(path))

    return found_paths

