def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        commands = [commands]

    final_cmd = []
    for cmd in commands:
        if '$' in cmd:
            # replace other variables to make execution possible
            try:
                cmd = cmd.replace('${HOME}', os.getenv('HOME'))
                cmd = cmd.replace('${USER}', os.getenv('USER'))
                cmd = cmd.replace('${HOME}/', os.path.sep)
                cmd = cmd.replace('$/', os.path.sep)
                cmd = cmd.replace("$\", str(os.path.join(os.getenv('HOME'), os.path.sep)))
                cmd = cmd.replace("$\\$", str(os.path.join(os.getenv('HOME'), os.path.sep)))
            except KeyError:
                pass
        final_cmd.append(cmd)

    print(f"Running command: {' '.join(final_cmd)}")
    if verbose:
        subprocess.run(final_cmd, cwd=cwd, env=env, capture_output=not hide_stderr)
    else:
        subprocess.run(final_cmd, cwd=cwd, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

