from typing import Optional, Set

def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """

    if roots is None:
        roots = set()

    for subject in graph.subjects(prop):
        indices = {}
        for triple in list(graph.triples((subject, None, None))):
            index = tuple(sorted(list(triple)[1:]))

            if index not in indices:
                indices[index] = []
            indices[index].append(subject)

        for index, subjcets in indices.items():
            farthestSubject = subjcets[-1]
            for subj in subjcets:
                if subj not in roots:
                    roots.add(subj)
                else:
                    # one is root
                    if set(farthestSubject) == set(subj):
                        return set()

            if farthestSubject not in roots:
                return set(farthestSubject)

    return roots

