from rdflib import Graph, URIRef, Node
from collections import defaultdict, Set

def find_roots(graph: Graph, prop: URIRef, roots: Set[Node] = None) -> Set[Node]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """

    if roots is None:
        roots = set()

    # Create a dictionary from the graph where keys are type and their values are List of nodes
    type_nodes = defaultdict(list)

    for sub, pred, obj in graph:
        type_nodes[sub][pred] = obj

    for sub in type_nodes:
        # If a node has a subClassOf relationship with no parent, it is a root
        if prop not in type_nodes[sub]:
            roots.add(sub)

    # Run a breadth-first search to find all nodes that are related to a root by RDFS.subClassOf or SKOS.broader
    to_traverse = {root: 0 for root in roots}
    visited = set(roots)
    while to_traverse:
        next_level = {}
        for node in to_traverse:
            for pred, children in type_nodes.items():
                if node in children[prop]:
                    if pred not in next_level:
                        next_level[pred] = set()
                    next_level[pred].update(children[prop][node])
                    visited.update(children[prop][node])
        to_traverse = next_level

    return roots

