def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """

    def resolve(seq):
        if not isinstance(seq, Sequence):
            return seq, None
        elif isinstance(seq, str):
            return [seq], str
        elif isinstance(seq, list):
            if all(isinstance(item, Sequence) for item in seq):
                return seq, list
            elif all(isinstance(item, str) for item in seq):
                return seq, list
            else:
                return resolve(seq[0])
        else:
            raise TypeError(f"Unsupported sequence type: {type(seq)}")

    sequence, type_ = resolve(seq)
    if bufsize is not None:
        sequence = sequence[:bufsize]
    return (sequence, type_)

