from typing import Set, Tuple, Callable, Set

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    from html.parser import HTMLParser

    class TagFinder(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.tags = set()
            selfFound = False
            self.codeFound = False

        def handle_starttag(self, tag: str, attrs: list):
            if not selfFound:
                self.tags.add(tag)
            if tag == 'code':
                self.codeFound = True
            if self.codeFound:
                selfFound = False

        def handle_endtag(self, tag: str):
            if tag == 'code':
                self.codeFound = False

        def handle_data(self, data):
            if selfFound:
                self.tags.add(data.strip())

    parser = TagFinder()
    parser.feed(text)

    replaced_text = text
    if replacer:
        for tag in parser.tags:
            replaced_text = replaced_text.replace(tag, replacer(tag))

    return parser.tags, replaced_text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    def add_linkification(attrs, link_text):
        attrs.append(("href", link_text))
        attrs.append(("class", "link-text"))

    import re
    pattern = re.compile(r"(http://\S+|\S+ http://\S+)")
    links = pattern.findall(text)

    for link in links:
        if "http://" in link:
            text = text.replace(link, link + " ")
            add_linkification([], link)
        else:
            text = text.replace(" " + link, link + " ")
            add_linkification([], link)

    return text

