from collections import defaultdict

def parse_diaspora_webfinger(document: str) -> DefaultDict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    # Check if the schema indicates JSON or XRD
    if document.lower().startswith("{"):
        # Parse JSON data
        data = json.loads(document)
    else:
        # Parse XML data
        root = ET.fromstring(document)
        try:
            # Check for XRD format
            profile = root.find(".//{http://alxr.org/ns/xrd}Person")
            if profile is not None and "webfinger" in profile.attrib:
                # Exclude 'rel' from 'webfinger' for API compatibility
                exploded wf = profile.attrib['webfinger[rel!="self"]'].split(", ")
                data = [{"rel": r, "href": et.text} for e in profile for r, et in exploded wf]
            else:
                # Parse generic webfinger information
                data = [e.attrib for e in root if e.tag == "{http://alxr.org/ns/xrd}Person"]
        except ET.ParseError:
            if document.lower().startswith("<?xml"):
                # Parse XHTML format (possibly incorrect format for Diaspora webfinger, leaving as is for now)
                data = [{e.tag: e.text} for e in ET.fromstring(document)]
            else:
                raise ValueError("Document format not supported for Diaspora webfinger parsing.")

    # Convert parsed data into a dictionary
    result = defaultdict(list)
    for entry in data:
        key = entry.get("__type__")
        if key:
            result[key].append(entry)
        else:
            for label, value in entry.items():
                if label not in result:
                    result[label] = []
                result[label].append(value)

    return result

