def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        url = f"https://{host}/host-meta"
        response = get(url)
        response.raise_for_status()

        tree = html.fromstring(response.content)
        # Assuming the host-meta document is in the 'host-meta' tag and the RDF is enclosed within it
        rdf_data = tree.xpath('//*[@rel="http://www.w3.org/ns/json-ld#context"]')
        if len(rdf_data) == 1:
            host_meta = json.loads(rdf_data[0].text)
            return DiasporaHostMeta(host_meta)
        else:
            raise ValueError("Unable to extract context from host-meta document")
    except RequestException as e:
        print(f"Failed to retrieve host-meta document for {host}: {e}")
        return None

