        """Check if value of arguments is between minimum and maximum values.

        :param args:
            - `lower_bound` (float): The lower bound of the range.
            - `upper_bound` (float): The upper bound of the range.
            - `arg_name` (str): The name of the argument being checked.

        Raises:
            ValueError: If the provided value is not within the specified range.
        """
        if "lower_bound" in args and "upper_bound" in args and "arg_name" in args:
            lower_bound = args["lower_bound"]
            upper_bound = args["upper_bound"]
            arg_name = args["arg_name"]

            if arg_name not in self.__class__.__annotations__:
                raise ValueError(f"The argument '{arg_name}' is not recognized by the class {self.__class__.__name__}.")

            if arg_name in self.__class__.__slots__ and not hasattr(self, arg_name):
                raise ValueError(f"The argument '{arg_name}' is not defined in the class {self.__class__.__name__}.")

            if arg_name in self.__class__.__annotations__ and not isinstance(lower_bound, type(self.__class__.__annotations__[arg_name])):
                raise ValueError(f"The lower bound for {arg_name} must be of the same type as the annotation.")
            if arg_name in self.__class__.__annotations__ and not isinstance(upper_bound, type(self.__class__.__annotations__[arg_name])):
                raise ValueError(f"The upper bound for {arg_name} must be of the same type as the annotation.")

            if "default_value" in args:
                default_value = args["default_value"]
                if default_value is None or not isinstance(args["default_value"], type(args["lower_bound"])):
                    default_value = None
                else:
                    if arg_name in self.__class__.__annotations__ and not isinstance(default_value, self.__class__.__annotations__[arg_name]):
                        default_value = None

            if not (isinstance(lower_bound, (int, float)) and isinstance(upper_bound, (int, float)) and issubclass(self.__class__.__annotations__[arg_name], (int, float))):
                raise ValueError(f"Both lower_bound and upper_bound must be of type {self.__class__.__annotations__[arg_name]} or a sub-type, and default_value must be of the same type.")

            if default_value is not None:
                if arg_name in self.__class__.__annotations__ and not isinstance(default_value, self.__class__.__annotations__[arg_name]):
                    raise ValueError(f"Default value for {arg_name} must be of the same type as the annotation.")
                if hasattr(self, arg_name) and not isinstance(getattr(self, arg_name), self.__class__.__annotations__[arg_name]):
                    setattr(self, arg_name, default_value)

            if arg_name in self.__class__.__annotations__ and not isinstance(getattr(self, arg_name), (int, float)):
                raise ValueError(f"The value of {arg_name} for {self.__class__.__name__} is not of the same type as the annotation.")

            if not (arg_name not in self.__class__.__annotations__ or hasattr(self, arg_name) and isinstance(getattr(self, arg_name), (int, float))):
                raise ValueError(f"The value of {arg_name} for {self.__class__.__name__} is not accounted for.")

            if argument_name not in self.__class__.__annotations__ or hasattr(self, argument_name) and type(getattr(self, argument_name)) is not self.__class__.__annotations__[argument_name]:
