class ComplexArgumentType(Element):
    """
    Representation of a complex argument type in a command-line application
    """
    ID = "ComplexArgumentType"

    @classmethod
    def create_type(cls, subcommand, type_name, option_name, spec_option):
        """
        Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """

        if type_name in cls.__subclasses__() and spec_option['range'] == 'enumerated':
            return ComplexEnumeratedArgumentType(subcommand, type_name, option_name, spec_option)
        elif type_name in cls.__subclasses__() and spec_option['range'] == 'string_list':
            return ComplexStringListArgumentType(subcommand, type_name, option_name, spec_option)
        elif type_name in cls.__subclasses__() and spec_option['range'] == 'multichoice':
            return ComplexMultichoiceArgumentType(subcommand, type_name, option_name, spec_option)
        elif type_name in cls.__subclasses__() and spec_option['range'] == 'boolean':
            return ComplexBooleanArgumentType(subcommand, type_name, option_name, spec_option)
        else:
            raise ValueError("Unknown type: " + type_name)

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    for arg in args:
        if 'control' in arg:
            control_args[arg] = None
        elif 'nested' in arg:
            nested_args[arg] = None

    return control_args, nested_args

