def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments"""

    # If the last argument is an int, it's a number of bytes.
    if isinstance(values_dict[-1], int):
        values_dict[-1] = int(values_dict.pop())

    # If the last argument is a float, it's a floating-point number.
    elif isinstance(values_dict[-1], float):
        values_dict[-1] = float(values_dict.pop())

    # If the last argument is a boolean, it's true if it's absent or something with 0, and false otherwise.
    elif isinstance(values_dict[-1], str):
        if values_dict.pop() == '1':
            values_dict[-1] = True
        else:
            values_dict[-1] = False

    # If we have a custom parser, convert it to the type depending on the default type.
    if parser_name == 'microdnf':
        values_dict['arch'] = Arch(values_dict.pop() if 'arch' not in values_dict else values_dict.pop())

    # Remove the modified arguments from the list.
    for _ in range(len(values_dict) - 1):
        values_dict.pop()

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, value in values_dict.items():
        if key in self.convert_type_dict:
            values_dict[key] = self.convert_type_dict[key](value)

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, value in values_dict.items():
        if isinstance(value, str):
            if value.isdigit():
                values_dict[key] = int(value)
            elif value.lower() in ['true', 'false']:
                values_dict[key] = (value.lower() == 'true')
            elif value == 'None':
                values_dict[key] = None
            elif value.startswith('http'):
                values_dict[key] = Uri.parse(value)
            else:
                values_dict[key] = Literal(value)

import os
import yaml

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """

    spec = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.yaml'):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    data = yaml.safe_load(f)
                    spec.update(data)
    return spec

import json
import os

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_dict = {}
    if os.path.exists(plugin_dir):
        for root, dirs, files in os.walk(plugin_dir, topdown=False):
            for file in files:
                if file.endswith('.json'):
                    file_path = os.path.join(root, file)
                    with open(file_path, mode='r') as f:
                        data = json.load(f)
                        for key, value in data.items():
                            if not isinstance(value, dict):
                                spec_dict[f"{root}/{key}"] = value
                            else:
                                deeply_nested = get_plugin_spec_flatten_dict(os.path.join(root, key))
                                for k, v in deeply_nested.items():
                                    spec_dict[f"{root}/{key}]/{v}"] = v
    return spec_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    flat_dict = dict()
    # Assume plugin_dir contains a file named plugin_specs.json
    try:
        with open(os.path.join(plugin_dir, 'plugin_specs.json'), 'r') as file:
            spec = json.load(file)
            flat_dict.update(spec)
    except FileNotFoundError:
        pass

    flattened_flat_dict = {}
    def flatten_dict_recursively(element, path=''):
        nonlocal flattened_flat_dict
        if isinstance(element, dict):
            for key, value in element.items():
                flatten_dict_recursively(value, path + key + '.' if path else key + '.')
        elif isinstance(element, list):
            for i, value in enumerate(element):
                flatten_dict_recursively(value, path + str(i) + '.')
        else:
            flattened_flat_dict[path] = element

    flatten_dict_recursively(flat_dict)
    return flattened_flat_dict

